function yuan(n){return `${n<0?'-':'+'}¥${Math.abs(n).toLocaleString()}`}
function header(title,desc,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function card(title,body,cls=''){return `<section class="card ${cls}"><h2 class="section-title">${title}</h2>${body}</section>`}
function renderNav(){document.querySelector('#nav').innerHTML=nav.map(x=>`<button class="${state.page===x[0]?'active':''}" data-page="${x[0]}"><span class="nav-icon">${x[1]}</span>${x[2]}</button>`).join('')}
function dashboard(){return header('你好，秾工诚 👋','今天也向更从容的未来靠近一点。')+`<div class="grid grid-4"><div class="card stat-card"><span class="label">总资产</span><div class="value">¥${state.panel.totalMoney.toLocaleString()}</div><span class="delta">↑ 较上月 +¥260</span></div><div class="card stat-card"><span class="label">本月收入</span><div class="value">¥${state.panel.monthlyIncome.toLocaleString()}</div><span class="delta">↑ 生活费已到账</span></div><div class="card stat-card"><span class="label">本月支出</span><div class="value">¥${state.panel.monthlyExpenses.toLocaleString()}</div><span class="delta warn">预算使用 ${Math.round(state.panel.monthlyExpenses/(state.panel.monthlyBudget||1)*100)}%</span></div><div class="card stat-card"><span class="label">本月储蓄</span><div class="value">¥${(state.panel.monthlyIncome-state.panel.monthlyExpenses).toLocaleString()}</div><span class="delta">本月结余</span></div></div><div class="dashboard-top" style="margin-top:18px"><section class="card health"><h2>你的财务健康度</h2><p>收支平衡，储蓄习惯正在养成</p><div class="health-score">78<span> / 100</span></div><div class="mini-progress"><i style="width:78%"></i></div><small>比上月提升 3 分 · 当前状态：稳健成长</small></section>${card('快速开始',`<div class="quick-grid"><button class="quick" data-page="assets"><span>＋</span>记一笔</button><button class="quick" onclick="openGoal()"><span>◎</span>存钱目标</button><button class="quick" data-page="ai"><span>✦</span>问问 AI</button><button class="quick" data-page="learn"><span>▤</span>学一课</button><button class="quick" data-page="risk"><span>◉</span>风险测评</button><button class="quick" data-page="lab"><span>◈</span>开始挑战</button></div>`)}</div><div class="grid grid-2" style="margin-top:18px">${card('本月预算进度',budgetRows())}${card('需要留意',`<div class="alert"><span class="alert-icon">🛍️</span><div><b>本月购物支出偏高</b><p>购物日用 ¥306，主要是那双 ¥199 的运动鞋，属于一次性消费。</p></div></div><div class="alert"><span class="alert-icon">⏰</span><div><b>毕业旅行，距目标还差 ¥1,320</b><p>每月存 ¥200，7 个月就能按计划抵达。</p></div></div>`)}</div>`}
function budgetRows(){const budget=state.panel.monthlyBudget||1,expenses=state.panel.monthlyExpenses||0;let p=Math.round(expenses/budget*100);return `<div class="budget-row"><b>总预算</b><div><div class="progress ${p>85?'warn':''}"><i style="width:${p}%"></i></div><small class="muted">已使用 ¥${expenses.toLocaleString()} / ¥${state.panel.monthlyBudget.toLocaleString()}</small></div><b>${p}%</b></div><div class="budget-row"><b>餐饮</b><div><div class="progress"><i style="width:39%"></i></div><small class="muted">¥276 / ¥700</small></div><b>39%</b></div><div class="budget-row"><b>购物</b><div><div class="progress warn"><i style="width:77%"></i></div><small class="muted">¥306 / ¥400</small></div><b>77%</b></div><button class="link-btn" onclick="openBudget()">调整本月预算 →</button>`}
function assets(){let rows=state.transactions.map(t=>`<tr><td>${t[0]}</td><td><b>${t[1]}</b></td><td><span class="tag ${t[3]<0?'expense':''}">${t[2]}</span></td><td style="color:${t[3]<0?'#d76463':'#159786'};font-weight:bold">${yuan(t[3])}</td></tr>`).join('');return header('资产管理','把每一笔钱看清楚，也把未来安排明白。','<button class="primary-btn" onclick="openTransaction()">＋ 记一笔</button>')+`<div class="grid grid-3"><div class="card stat-card"><span class="label">可用现金</span><div class="value">¥4,280</div><span class="delta">3 个账户</span></div><div class="card stat-card"><span class="label">目标储蓄</span><div class="value">¥860</div><span class="delta">正在为梦想蓄力</span></div><div class="card stat-card"><span class="label">本月结余</span><div class="value">¥614</div><span class="delta">结余率 42%</span></div></div><div class="grid grid-2" style="margin-top:18px">${card('收支趋势',`<div id="trendChart" class="chart"></div>`)}${card('消费分类',`<div id="pieChart" class="chart"></div>`)}</div><div class="grid grid-2" style="margin-top:18px">${card('目标储蓄计划',state.goals.map(g=>`<div class="budget-row"><span style="font-size:22px">${g.icon}</span><div><b>${g.name}</b><div class="progress"><i style="width:${g.saved/g.target*100}%"></i></div><small class="muted">¥${g.saved} / ¥${g.target}</small></div><b>${Math.round(g.saved/g.target*100)}%</b></div>`).join('')+'<button class="link-btn" onclick="openGoal()">＋ 新建储蓄目标</button>')}${card('最近交易',`<table class="table"><thead><tr><th>时间</th><th>描述</th><th>分类</th><th>金额</th></tr></thead><tbody>${rows}</tbody></table>`)}</div>`}
function ai(){return `<div class="ai-page">${header('AI 财富管家','陪你把每一个小目标，变成看得见的进步。')}<section class="card chat ai-chat-full"><h2 class="section-title">青财 AI <span class="tag">${aiEnabled()?'已连接 AI':'本地模拟'}</span><small onclick="openAiSettings()">⚙ AI 设置</small></h2><div class="messages" id="messages">${messagesHtml()}</div><div class="preset-row"><span class="preset-label">试试这样问</span>${aiPresets.map((p,i)=>`<button class="preset-chip" onclick="askAiPreset(${i})">${p[0]}</button>`).join('')}</div><form class="chat-input" id="chatForm"><textarea id="chatInput" rows="1" required placeholder="例如：我该如何合理安排生活费？"></textarea><button class="primary-btn">发送</button></form></section><div class="disclaimer">${disclaimer}</div></div>`}
function risk(){return header('风险预警中心','及时发现小风险，守住成长的安全感。','<button class="primary-btn" onclick="showToast(\'测评已刷新，结果：稳健成长型\')">重新测评</button>')+`<div class="grid grid-2"><div class="card"><h2 class="section-title">当前风险等级</h2><div class="risk-level"><div class="gauge"><b>中低</b></div><div><b style="color:#d88930">需要留意</b><p class="muted">整体可控，避免娱乐支出继续增长。</p></div></div></div>${card('现金流预测',`<b>未来 14 天可用余额 ¥520</b><p class="muted">按当前节奏，资金充足；建议先预留 ¥500 应急金。</p>`)}${card('信用守护',`<b>暂无信用逾期风险</b><p class="muted">保持“借贷不超还款能力”的好习惯。</p>`)}${card('理财偏好画像',`<div class="risk-level"><div class="gauge"><b>稳健</b></div><div><b>成长积累型</b><p class="muted">适合先建立应急金，再学习低风险资产知识。</p></div></div><div class="disclaimer">${disclaimer}</div>`)}</div><div class="grid grid-2" style="margin-top:18px">${card('风险信号',`<div class="alert"><span class="alert-icon">⚠️</span><div><b>大额消费提醒</b><p>本月购物日用 ¥306，其中运动鞋 ¥199；建议下月大额消费前先放一晚再决定。</p></div></div><div class="alert"><span class="alert-icon">🛡️</span><div><b>防诈骗小提醒</b><p>不轻信“高收益、零风险”宣传，不向陌生账户转账。</p></div></div>`)}${card('改善小行动',`<div class="category-list"><div class="category"><span class="dot"></span><span>设置单笔消费超过 ¥50 的提醒</span><button class="link-btn" onclick="showToast('大额消费提醒已开启')">开启</button></div><div class="category"><span class="dot"></span><span>完成一次反诈专题学习</span><button class="link-btn" data-page="learn">去学习</button></div><div class="category"><span class="dot"></span><span>建立 ¥500 的应急金</span><button class="link-btn" onclick="openGoal()">去设置</button></div></div>`)}</div>`}
function learn(){return header('金融学习中心','用容易懂的方式，练出一身财务底气。')+`<div class="grid grid-2"><div>${card('为你规划的学习路径',`<div class="course"><div class="course-icon">①</div><div><b>先学会做预算</b><small>3 节课 · 已完成 67%</small></div><button class="link-btn" onclick="showToast('已打开：预算的第一课')">继续</button></div><div class="course"><div class="course-icon">②</div><div><b>建立你的第一笔储蓄</b><small>2 节课 · 待开始</small></div><button class="link-btn" onclick="showToast('已加入学习计划')">开始</button></div><div class="course"><div class="course-icon">③</div><div><b>认识风险与信用</b><small>4 节课 · 待开始</small></div><button class="link-btn" onclick="showToast('已加入学习计划')">开始</button></div>`)}${card('金融知识小测',`<b>“高收益、零风险”的理财宣传值得相信吗？</b><label class="option"><input type="radio" name="quiz" value="0"> A. 值得，收益越高越好</label><label class="option"><input type="radio" name="quiz" value="1"> B. 不值得，应警惕风险与诈骗</label><button class="primary-btn" onclick="gradeQuiz()">提交答案</button>`)}</div>${card('课程广场',`<div class="course"><div class="course-icon">💰</div><div><b>预算不是“抠门”</b><small>用 50/30/20 法则安排生活费</small></div><button class="link-btn" onclick="showToast('课程已开始播放（Demo）')">学习</button></div><div class="course"><div class="course-icon">🌱</div><div><b>储蓄的复利小魔法</b><small>从第一笔应急金开始</small></div><button class="link-btn" onclick="showToast('课程已开始播放（Demo）')">学习</button></div><div class="course"><div class="course-icon">🕵️</div><div><b>校园贷与反诈防线</b><small>识别常见金融陷阱</small></div><button class="link-btn" onclick="showToast('课程已开始播放（Demo）')">学习</button></div><div class="course"><div class="course-icon">📈</div><div><b>基金、保险、债券入门</b><small>先理解，再决定</small></div><button class="link-btn" onclick="showToast('课程已开始播放（Demo）')">学习</button></div>`)}</div></div>`}
function lab(){return header('模拟金融实验室','用虚拟本金大胆练习，在真实世界更从容。')+`<section class="card lab-hero"><h2>你的虚拟实验账户</h2><p class="muted">所有金额仅用于学习模拟，不涉及真实资金与交易。</p><div class="lab-amount">¥3,000 <small>虚拟本金</small></div><button class="primary-btn" style="margin-top:12px" onclick="showToast('模拟账户已重置为 ¥3,000')">重置实验账户</button></section><div class="grid grid-3" style="margin-top:18px"><div class="scenario" onclick="runChallenge('毕业租房预算')"><span>🏠</span><b>毕业租房预算</b><small class="muted">在 ¥6,000 月薪下安排房租、通勤与储蓄</small></div><div class="scenario" onclick="runChallenge('实习工资管理')"><span>💼</span><b>实习工资管理</b><small class="muted">让第一份工资不再“月光”</small></div><div class="scenario" onclick="runChallenge('考研备考资金')"><span>🎓</span><b>考研备考资金</b><small class="muted">平衡培训、资料与日常开销</small></div></div><div class="grid grid-2" style="margin-top:18px">${card('模拟资产组合',`<p class="muted">选择虚拟配置比例，看看不同风险下的波动。</p><div class="budget-row"><b>稳健储蓄</b><div class="progress"><i style="width:60%"></i></div><b>60%</b></div><div class="budget-row"><b>债券基金</b><div class="progress"><i style="width:25%;background:#5c91e8"></i></div><b>25%</b></div><div class="budget-row"><b>权益基金</b><div class="progress"><i style="width:15%;background:#ef9c44"></i></div><b>15%</b></div><button class="primary-btn" onclick="showToast('模拟运行完成：组合波动较低，适合稳健学习阶段')">运行 30 天模拟</button><div class="disclaimer">${disclaimer}</div>`)}${card('最近复盘',`<b>实习工资挑战 · 获得 86 分</b><p class="muted">你成功预留了应急金，但餐饮占比略高。下次可尝试提前设定每周餐饮上限。</p><div class="tag">解锁「理性规划者」进度 +1</div>`)}</div>`}
function growth(){return header('青年成长账户','每一份自律，都在成为你未来的底气。')+`<div class="grid grid-3"><section class="card level-card"><div class="level-num">Lv.3</div><b>稳步前行</b><p class="muted">距离下一等级还需 180 成长值</p><div class="progress"><i style="width:62%"></i></div></section>${card('本周成长值',`<div class="value" style="font-size:35px;font-weight:800">+72</div><p class="muted">来自学习 30 · 预算执行 22 · 储蓄 20</p>`)}${card('青年权益',`<b>🎒 校园成长礼包</b><p class="muted">完成“反诈防线”课程，解锁校园活动优先报名资格。</p><button class="link-btn" data-page="learn">去完成 →</button>`)}</div><div class="grid grid-2" style="margin-top:18px">${card('我的成长徽章',`<div class="badges"><div class="badge"><div class="badge-icon">🌱</div>第一笔储蓄</div><div class="badge"><div class="badge-icon">📒</div>连续记账 7 天</div><div class="badge"><div class="badge-icon">🛡️</div>风险小卫士</div><div class="badge locked"><div class="badge-icon">🚀</div>目标达人</div></div>`)}${card('成长记录',`<div class="timeline"><div class="timeline-item"><b>完成《预算不是抠门》课程</b><small>今天 · 获得 30 成长值</small></div><div class="timeline-item"><b>毕业旅行存入 ¥300</b><small>8月30日 · 获得 20 成长值</small></div><div class="timeline-item"><b>连续记账 7 天</b><small>8月28日 · 获得「认真生活」徽章</small></div></div>`)}</div>`}
function settings(){return header('设置与授权','你的数据由你掌控。')+`<div class="grid grid-2 settings">${card('个人信息',`<form id="profileForm"><div class="field"><label>昵称</label><input value="秾工诚" required></div><div class="field"><label>身份</label><select><option>在校大学生</option><option>研究生</option><option>初入职场</option></select></div><div class="field"><label>学校 / 公司</label><input value="南京农业大学"></div><div class="field"><label>成长阶段</label><select><option>校园探索期</option><option>职场起步期</option></select></div><button class="primary-btn">保存修改</button></form>`)}${card('数据授权管理',`<div class="course"><div><b>账户与交易数据</b><small>用于生成资产看板与预算分析</small></div><button class="link-btn" onclick="showToast('授权状态已更新（Demo）')">已授权</button></div><div class="course"><div><b>个性化学习推荐</b><small>用于生成适合你的学习路径</small></div><button class="link-btn" onclick="showToast('授权状态已更新（Demo）')">已授权</button></div><div class="disclaimer">本演示仅在浏览器本地保存模拟数据，不会上传或处理真实财务信息。</div>`)}</div><div class="card" style="margin-top:18px"><h2 class="section-title">服务说明</h2><p class="muted">${disclaimer}</p><p class="muted">所有模拟实验、财务建议和风险提示仅用于金融素养教育与辅助规划展示。</p></div>`}
const pages={dashboard,assets,ledger:dashboard,ai,risk,learn,lab,growth,settings};
function render(){state.page=location.hash.slice(1)||state.page;renderNav();document.querySelector('#crumb').textContent=nav.find(x=>x[0]===state.page)?.[2]||'青财智管';document.querySelector('#view').innerHTML=pages[state.page]();document.querySelectorAll('[data-page]').forEach(el=>el.addEventListener('click',()=>{location.hash=el.dataset.page;document.querySelector('.sidebar').classList.remove('open')})); if(state.page==='assets')setTimeout(drawCharts,0);if(state.page==='ai')bindChat();if(state.page==='settings')document.querySelector('#profileForm').addEventListener('submit',e=>{e.preventDefault();showToast('个人信息已保存（本地模拟）')})}
function drawCharts(){if(!window.echarts)return;let trend=echarts.init(document.querySelector('#trendChart')),pie=echarts.init(document.querySelector('#pieChart'));trend.setOption({tooltip:{trigger:'axis'},grid:{left:35,right:15,top:25,bottom:25},xAxis:{type:'category',data:['4月','5月','6月','7月','8月','9月'],axisLine:{show:false},axisTick:{show:false}},yAxis:{type:'value',splitLine:{lineStyle:{color:'#edf3f2'}},axisLine:{show:false}},series:[{data:[1800,2100,2400,2700,3000,3260],type:'line',smooth:true,symbolSize:7,lineStyle:{color:'#28b6a4',width:3},itemStyle:{color:'#28b6a4'},areaStyle:{color:'#d9f5ef'}}]});pie.setOption({tooltip:{trigger:'item'},legend:{bottom:0,textStyle:{color:'#789093'}},series:[{type:'pie',radius:['50%','72%'],label:{show:false},data:[{value:306,name:'购物日用',itemStyle:{color:'#d4e4e2'}},{value:276,name:'餐饮',itemStyle:{color:'#28b6a4'}},{value:113,name:'社交娱乐',itemStyle:{color:'#ef9c44'}},{value:81,name:'学习',itemStyle:{color:'#5c91e8'}},{value:49,name:'交通通讯',itemStyle:{color:'#8575d6'}},{value:48,name:'水电水果',itemStyle:{color:'#b9ddd6'}}]}]});window.addEventListener('resize',()=>{trend.resize();pie.resize()},{once:true})}
const aiPresets=[['砍头息骗局','工诚，这个不能签，是典型的「砍头息 + 求职培训贷」双套路。法律上利息不能预先从本金里扣，你实际只拿到 9,000，就只该按 9,000 还本计息，合同写 10,000 却只放 9,000 本身就不合法；所谓「审核费、就业指导费」就是把利息藏进费用里，真实成本远不止 9.6%。「凭学生证零门槛、包就业」多半是话术，最后债在你身上。下一步：别签字、别交身份证和银行卡；已经签了的话保存好合同和转账记录，找学校资助中心或拨 12378 咨询。','我最近看中了一个‘求职培训贷’项目。凭学生证就能零门槛办理，虽然合同上写的是借10000元，但放款时会先扣除1000元的‘平台审核费’和‘就业指导费’，实际到账9000元。不过平台承诺，后续我只需要按10000元的本金、以月息0.8%（年化9.6%）来分期还款，这样算下来远低于国家规定的利率标准。'],['这个月我的钱都花在哪了？','工诚，本月共支出 ¥873，预算 ¥1,200 用了 73%。其中购物日用 ¥306（主要是那双 ¥199 的运动鞋）、餐饮含奶茶 ¥276、社交娱乐 ¥113、学习 ¥81、交通通讯 ¥49、水电水果 ¥48。日常开销其实很稳，多出来的部分基本是一次性购物。'],['生活费怎么分配比较合理？','你每月生活费 ¥1,200、家教 ¥300，合计 ¥1,500。按 50/30/20：¥750 吃饭日用、¥450 社交与买书、¥300 先存起来。建议生活费一到账就把 ¥300 转进储蓄，剩下的再花——家教那笔也直接进储蓄，别混进日常。'],['食堂外卖花得有点多，怎么控制？','你餐饮含奶茶一共 ¥276，占餐饮预算 39%，其实不算高。真想再省：① 奶茶从一周 2~3 杯降到 1~2 杯，一个月能省 ¥30 左右；② 室友聚餐 AA 控制在两周一次；③ 校园卡一次别充太多，¥100 一充更容易感知余额。'],['我想存钱买台新电脑，怎么安排？','按你本月结余 ¥627 来算，一台 ¥3,000 的电脑大约 5 个月。不过你已经有毕业旅行（还差 ¥1,320）和考证两个目标，建议单独建一个「电脑基金」，每月从结余里固定放 ¥300，别和旅行基金的钱混在一起。'],['学生想学理财，应该从哪开始？','建议按顺序来：① 先存出 ¥500 应急金（你现在可动用 ¥2,400，完全够）；② 把记账坚持下来，你已经记了 22 笔，很扎实；③ 了解货币基金、国债这类低风险工具；④ 想练手先去模拟实验室。学生阶段，不超支比收益率重要得多。']];
function aiAnswer(q){const hit=aiPresets.find(p=>p[0]===q);if(hit)return hit[1];const rules=[[/餐饮|外卖|食堂|奶茶|咖啡|吃/,'你本月餐饮含奶茶 ¥276，占餐饮预算的 39%，不算高。真想再省，奶茶从一周 2~3 杯降到 1~2 杯，一个月就能省下 ¥30 左右。'],[/生活费|分配|预算|规划/,'按 50/30/20 安排：生活费 ¥1,200 里，¥600 吃饭日用、¥360 社交与买书、¥240 先存起来；家教那 ¥300 建议直接进储蓄。先存后花，比月底剩多少存多少容易坚持得多。'],[/存|储蓄|攒|目标|电脑|旅行/,'你本月结余 ¥627。可以先建一个专门的储蓄目标，把大目标拆成每月固定金额；记得别和毕业旅行、考证的钱混在一起，分开管更清楚。'],[/理财|基金|投资|收益|股票/,'学生阶段先做两件事：存够 ¥500 应急金、把记账坚持下去；之后可以从货币基金、国债等低风险工具开始了解，再到模拟实验室练手，切勿追求高收益。'],[/风险|安全|诈骗|网贷|校园贷|砍头息|培训贷|刷单|贷款|高利/,'这种事一定要警惕，很可能是骗局：不要签字、不要向陌生账户转账，也不要出借身份证和银行卡。凡是「先扣费」「先垫钱」「零门槛包就业」的说法，都先放一放，找学校老师或拨 12378 核实。'],[/支出|花钱|消费|账单|花在哪/,'本月你共支出 ¥873，占预算的 73%。其中购物日用 ¥306、餐饮含奶茶 ¥276、社交娱乐 ¥113、学习 ¥81、交通通讯 ¥49、水电水果 ¥48，整体没有超支，超出的主要是一次性购物。']];const r=rules.find(([re])=>re.test(q));return r?r[1]:'我可以帮你分析支出、规划生活费、设置储蓄目标，也能讲讲适合学生的理财入门知识。你可以直接问我，也可以点上面的推荐问题试试看～'}
const escHtml=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function messagesHtml(){return state.messages.map(m=>`<div class="message ${m[0]==='user'?'user':''}"><div class="avatar">${m[0]==='user'?'秾':'Q'}</div><div class="bubble">${escHtml(m[1])}</div></div>`).join('')}
function scrollMessages(){const box=document.querySelector('#messages');if(box)box.scrollTop=box.scrollHeight}
function paintMessages(){const box=document.querySelector('#messages');if(box){box.innerHTML=messagesHtml();box.scrollTop=box.scrollHeight}}
function aiFinanceContext(){const p=state.panel,used=p.monthlyBudget?Math.round(p.monthlyExpenses/p.monthlyBudget*100):0,goals=state.goals.map(g=>`${g.name}（目标 ¥${g.target}，已存 ¥${g.saved}，完成 ${g.target?Math.round(g.saved/g.target*100):0}%）`).join('；'),recent=state.transactions.slice(0,30),flows=recent.map(t=>`${t[0]} ${t[1]}（${t[2]}）${t[3]<0?'支出':'收入'} ¥${Math.abs(t[3])}`).join('；');return ['【用户画像】',`${USER_PROFILE.name}，${USER_PROFILE.age} 岁，${USER_PROFILE.gender}，${USER_PROFILE.school}${USER_PROFILE.major}专业${USER_PROFILE.grade}，在${USER_PROFILE.city}，${USER_PROFILE.living}。`,`收入来源：${USER_PROFILE.income}`,`消费习惯：${USER_PROFILE.habits}`,`储蓄动机：${USER_PROFILE.motivation}`,`近况：${USER_PROFILE.current}`,`对钱的心情：${USER_PROFILE.worry}`,'【用户当前财务数据】',`总资产：¥${p.totalMoney}`,`本月收入：¥${p.monthlyIncome}（主要为生活费）`,`本月支出：¥${p.monthlyExpenses}`,`本月预算：¥${p.monthlyBudget}（已使用 ${used}%）`,`本月结余：¥${p.monthlyIncome-p.monthlyExpenses}`,`储蓄目标：${goals||'暂无'}`,`本月流水（共 ${recent.length} 笔）：${flows||'暂无记录'}`,'【数据说明】以上均为系统提供的真实数据，请严格基于这些数字回答，不要自行编造或推测未提供的金额；流水为系统记录，若与分类汇总略有出入，以汇总数字为准。'].join('\n')}
async function callAi(messages,stream,onDelta){const c=aiEffectiveConfig(),url=String(c.baseUrl).replace(/\/+$/,'')+'/chat/completions';const res=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+c.apiKey},body:JSON.stringify({model:c.model,temperature:c.temperature,max_tokens:c.maxTokens,stream:!!stream,messages})});if(!res.ok)throw new Error((await res.text())||('AI 接口返回 '+res.status));if(!stream){const data=await res.json();return String((data&&data.choices&&data.choices[0]&&data.choices[0].message&&data.choices[0].message.content)||'').trim()}if(!res.body)throw new Error('当前环境不支持流式响应');const reader=res.body.getReader(),decoder=new TextDecoder();let buf='',full='';for(;;){const chunk=await reader.read();if(chunk.done)break;buf+=decoder.decode(chunk.value,{stream:true});const lines=buf.split('\n');buf=lines.pop()||'';for(const line of lines){const s=line.trim();if(s.indexOf('data:')!==0)continue;const p=s.slice(5).trim();if(!p||p==='[DONE]')continue;try{const j=JSON.parse(p),d=j.choices&&j.choices[0]&&j.choices[0].delta&&j.choices[0].delta.content;if(d){full+=d;if(onDelta)onDelta(full)}}catch(e){}}}return full.trim()}
async function askAi(q,presetAnswer){const fb=()=>presetAnswer||aiAnswer(q);state.messages.push(['user',q]);if(!aiEnabled()){state.messages.push(['ai',fb()]);render();scrollMessages();return}state.messages.push(['ai','正在思考…']);render();scrollMessages();const last=()=>state.messages[state.messages.length-1];try{const history=state.messages.slice(0,-1).map(m=>({role:m[0]==='user'?'user':'assistant',content:m[1]}));const msgs=[{role:'system',content:AI_SYSTEM_PROMPT+'\n\n'+aiFinanceContext()}].concat(history);let text='';try{text=await callAi(msgs,true,partial=>{last()[1]=partial;paintMessages()})}catch(e){text=''}if(!text)text=await callAi(msgs,false);last()[1]=String(text||'').trim()||fb()}catch(e){last()[1]=fb();showToast('AI 接口调用失败，已回退到本地模拟回答')}render();scrollMessages()}
function askAiPreset(i){const p=aiPresets[i];if(p)return askAi(p[2]||p[0],p[1])}
function openAiSettings(){const c=aiEffectiveConfig();openModal(`<h2>AI 接口设置</h2><p class="muted">填写任意 OpenAI 兼容接口（DeepSeek / 智谱 GLM / Kimi / 硅基流动 等）即可启用真实问答；Key 留空则使用本地模拟回答。</p><form id="aiForm"><div class="field"><label>接口地址 Base URL</label><input name="baseUrl" value="${escHtml(c.baseUrl)}" placeholder="https://api.deepseek.com/v1" required></div><div class="field"><label>模型名</label><input name="model" value="${escHtml(c.model)}" placeholder="deepseek-chat" required></div><div class="field"><label>API Key</label><input name="apiKey" type="password" value="${escHtml(c.apiKey)}" placeholder="sk-..."></div><div class="disclaimer">⚠️ Key 只保存在本机浏览器。若写进代码并在公网部署，任何人都能查看源码并盗用，请勿使用有价值的密钥。</div><div class="modal-actions"><button type="button" data-close class="cancel-btn">取消</button><button class="primary-btn">保存并启用</button></div></form>`);document.querySelector('#aiForm').onsubmit=e=>{e.preventDefault();const vals=Object.fromEntries(new FormData(e.target).entries());try{localStorage.setItem('qingcai_ai_config',JSON.stringify(vals))}catch(err){}closeModal();showToast(vals.apiKey?'AI 接口已启用':'已切换为本地模拟回答');render()}}
function bindChat(){const f=document.querySelector('#chatForm');if(!f)return;const input=document.querySelector('#chatInput');const autosize=()=>{if(!input)return;input.style.height='auto';input.style.height=Math.min(input.scrollHeight+2,140)+'px'};const send=()=>{const q=((input&&input.value)||'').trim();if(!q)return;input.value='';autosize();askAi(q)};if(input){const coarse=!!(window.matchMedia&&window.matchMedia('(pointer:coarse)').matches);input.addEventListener('input',autosize);input.addEventListener('keydown',e=>{if(e.key!=='Enter'||e.shiftKey||e.isComposing||e.keyCode===229)return;if(coarse)return;e.preventDefault();send()});autosize()}f.addEventListener('submit',e=>{e.preventDefault();send()});scrollMessages()}
function openModal(content){let m=document.querySelector('#modal');m.innerHTML=`<div class="modal-box">${content}</div>`;m.classList.add('show');m.onclick=e=>{if(e.target===m)closeModal()};m.querySelectorAll('[data-close]').forEach(x=>x.onclick=closeModal)}function closeModal(){document.querySelector('#modal').classList.remove('show')}function openGoal(){openModal(`<h2>创建储蓄目标</h2><p class="muted">把想做的事，拆成每天都做得到的小计划。</p><form id="goalForm" class="form-grid"><div class="field"><label>目标名称</label><input required value="应急备用金"></div><div class="field"><label>目标金额</label><input required type="number" min="100" value="1000"></div><div class="field"><label>已存金额</label><input required type="number" min="0" value="0"></div><div class="field"><label>目标类别</label><select><option>应急储备</option><option>旅行</option><option>考证学习</option><option>租房押金</option></select></div><div class="modal-actions" style="grid-column:1/-1"><button type="button" data-close class="cancel-btn">取消</button><button class="primary-btn">创建目标</button></div></form>`);document.querySelector('#goalForm').onsubmit=e=>{e.preventDefault();let i=e.target.querySelectorAll('input');state.goals.push({name:i[0].value,target:+i[1].value,saved:+i[2].value,icon:'🎯'});closeModal();showToast('新的储蓄目标已创建');if(state.page==='assets')render()}}function openBudget(){openModal(`<h2>调整月度预算</h2><p class="muted">设置本月总预算，用于「今日概览」的预算进度。</p><form id="budgetForm"><div class="field"><label>本月总预算（元）</label><input type="number" min="0" step="0.01" value="${state.panel.monthlyBudget}" required></div><div class="modal-actions"><button type="button" data-close class="cancel-btn">取消</button><button class="primary-btn">保存预算</button></div></form>`);document.querySelector('#budgetForm').onsubmit=async e=>{e.preventDefault();const amount=Number(e.target.querySelector('input').value);if(!Number.isFinite(amount)||amount<0){showToast('请输入有效的预算金额');return}try{if(apiState.token){await callApi('/api/Panel/MonthlyBudget',{method:'POST',body:JSON.stringify(amount)})}state.panel.monthlyBudget=amount;closeModal();showToast(apiState.token?'月度预算已同步至账户':'预算已保存到本地模拟数据');render()}catch(error){showToast(error.message||'预算保存失败，请确认后端服务已启动')}}}function openTransaction(){openModal(`<h2>记录一笔收支</h2><form id="txForm" class="form-grid"><div class="field"><label>类型</label><select id="txType"><option value="expense">支出</option><option value="income">收入</option></select></div><div class="field"><label>金额（元）</label><input type="number" min="0.01" step="0.01" value="30" required></div><div class="field"><label>分类</label><select id="txCat"><option>餐饮</option><option>交通</option><option>购物</option><option>学习</option><option>娱乐</option><option>收入</option></select></div><div class="field"><label>描述</label><input value="日常消费" required></div><div class="modal-actions" style="grid-column:1/-1"><button type="button" data-close class="cancel-btn">取消</button><button class="primary-btn">保存记录</button></div></form>`);document.querySelector('#txForm').onsubmit=e=>{e.preventDefault();let f=e.target,amount=+f.querySelector('input[type=number]').value,isExp=f.querySelector('#txType').value==='expense';state.transactions.unshift(['刚刚',f.querySelector('input[value="日常消费"]')?.value||f.querySelectorAll('input')[1].value,f.querySelector('#txCat').value,isExp?-amount:amount]);if(isExp)state.spent+=amount;closeModal();showToast('交易已保存，资产看板已刷新');render()}}function gradeQuiz(){showToast(document.querySelector('input[name=quiz]:checked')?.value==='1'?'回答正确！获得 10 成长值 🎉':'再想想：投资与理财都伴随风险哦')}function runChallenge(name){showToast(`「${name}」已开始：请在模拟环境中完成预算安排`)}function showToast(msg){let t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),2800)}
function showNavHint(){try{if(sessionStorage.getItem('qingcai_menu_hint'))return}catch(e){}if(!window.matchMedia||!window.matchMedia('(max-width:980px)').matches)return;const btn=document.querySelector('#menuBtn'),hint=document.querySelector('#navHint');if(btn)btn.classList.add('pulse');if(hint)hint.classList.add('show')}
