function setSidebar(open){document.querySelector('.sidebar').classList.toggle('open',open);document.querySelector('#sidebarBackdrop').classList.toggle('show',open);hideNavHint()}document.querySelector('#menuBtn').onclick=()=>setSidebar(!document.querySelector('.sidebar').classList.contains('open'));document.querySelector('#sidebarBackdrop').onclick=()=>setSidebar(false);document.querySelector('#notificationBtn').onclick=()=>{location.hash='risk'};window.addEventListener('hashchange',render);render();

// Unified ASP.NET Core WebAPI client. Authentication is attached automatically after sign-in.
async function callApi(endpoint, options={}) {
  if(!API_ENABLED) throw new Error('当前为在线演示版，未连接后端服务，数据以本地模拟方式展示');
  const headers={'Content-Type':'application/json',...(options.headers||{})};
  if(apiState.token) headers.Authorization=`Bearer ${apiState.token}`;
  const response=await fetch(`${API_BASE}${endpoint}`,{...options,headers});
  if(!response.ok) throw new Error((await response.text())||`请求失败（${response.status}）`);
  if(response.status===204) return null;
  const text=await response.text();
  if(!text) return null;
  let payload;try{payload=JSON.parse(text)}catch{return text}
  return payload?.data??payload;
}
const dateText=value=>value?new Date(value).toLocaleDateString('zh-CN',{month:'short',day:'numeric'}):'刚刚';
function getField(obj,...keys){return keys.map(k=>obj?.[k]).find(v=>v!==undefined&&v!==null)}
function applyTransactions(list){
  if(!Array.isArray(list))return;
  state.transactions=list.map(t=>{const category=categories.find(c=>c.id===Number(getField(t,'categoryId','CategoryId')));return [dateText(getField(t,'createdAt','CreatedAt')),getField(t,'description','Description')||'未填写描述',category?.name||'未分类',Number(getField(t,'amount','Amount')||0),getField(t,'id','Id'),category?.id]});
  state.spent=Math.round(Math.abs(state.transactions.filter(t=>t[3]<0).reduce((sum,t)=>sum+t[3],0))*100)/100;
}
async function refreshFinance(){
  if(!apiState.token)return;
  const [accounts,transactions,assets,profile]=await Promise.all([callApi('/api/account'),callApi('/api/transaction'),callApi('/api/asset'),callApi('/api/userInfo')]);
  apiState.accounts=Array.isArray(accounts)?accounts:[]; apiState.assets=Array.isArray(assets)?assets:[]; apiState.profile=profile||null; applyTransactions(transactions);
  await refreshPanel();
}
function parseMoney(payload,...keys){
  if(payload===undefined||payload===null)return undefined;
  if(typeof payload==='number')return payload;
  if(typeof payload==='string'){const n=Number(String(payload).replace(/[^0-9.\-]/g,''));return Number.isFinite(n)?n:undefined}
  if(typeof payload==='object'){
    for(const key of keys){const n=parseMoney(payload[key]);if(n!==undefined)return n}
    for(const key of ['value','amount','money','total','balance','sum']){const n=parseMoney(payload[key]);if(n!==undefined)return n}
  }
  return undefined;
}
async function refreshPanel(){
  try{
    const [totalMoney,monthlyIncome,monthlyExpenses,monthlyBudget]=await Promise.all([callApi('/api/Panel/TotalMoney'),callApi('/api/Panel/MonthlyIncome'),callApi('/api/Panel/MonthlyExpenses'),callApi('/api/Panel/MonthlyBudget')]);
    const set=(key,payload,names)=>{const n=parseMoney(payload,...names);if(n!==undefined)state.panel[key]=n};
    set('totalMoney',totalMoney,['totalMoney','TotalMoney','total']);
    set('monthlyIncome',monthlyIncome,['monthlyIncome','MonthlyIncome','income']);
    set('monthlyExpenses',monthlyExpenses,['monthlyExpenses','MonthlyExpenses','expenses','expense']);
    set('monthlyBudget',monthlyBudget,['monthlyBudget','MonthlyBudget','budget']);
  }catch(error){/* 后端不可用时保留 Mock 面板数据 */}
}
async function connectAccount(mode,form){
  const email=form.email.value.trim(),password=form.password.value;
  if(!email||!password)throw new Error('请填写邮箱与密码');
  if(mode==='register')await callApi('/register',{method:'POST',body:JSON.stringify({email,password})});
  const login=await callApi('/login',{method:'POST',body:JSON.stringify({email,password})});
  const token=typeof login==='string'?login:(login?.token||login?.accessToken||login?.access_token);
  if(!token)throw new Error('登录成功但未识别到令牌，请检查后端登录返回字段');
  apiState.token=token;localStorage.setItem('qingcai_token',token);await refreshFinance();
}
function openAuth(){openModal(`<h2>连接青财账户</h2><p class="muted">登录后将读取本机 ASP.NET Core 服务中的账户、交易和资料数据。</p><form id="authForm"><div class="field"><label>邮箱</label><input type="email" name="email" placeholder="name@example.com" required></div><div class="field"><label>密码</label><input type="password" name="password" minlength="6" required></div><div class="modal-actions"><button type="button" data-close class="cancel-btn">稍后再说</button><button type="button" class="cancel-btn" id="registerBtn">注册并登录</button><button class="primary-btn">登录</button></div></form>`);const form=document.querySelector('#authForm');const submit=async mode=>{try{await connectAccount(mode,form);closeModal();showToast('账户已连接，数据已同步');render()}catch(error){showToast(error.message||'连接失败，请确认服务已启动')}};form.onsubmit=e=>{e.preventDefault();submit('login')};document.querySelector('#registerBtn').onclick=()=>submit('register')}
function accountName(type){return ['现金','微信','支付宝','工商银行','中国银行','中国农业银行','建设银行','南京银行','其他'][Number(type)]||'其他'}
function accountsPanel(){const rows=apiState.accounts.length?apiState.accounts.map(a=>`<div class="account-chip"><span>${['💵','🟩','🟦','🏦','🏛️'][Number(getField(a,'type','Type'))]||'💳'}</span><div><b>${getField(a,'name','Name')}</b><small>${accountName(getField(a,'type','Type'))}</small></div><strong>¥${Number(getField(a,'balance','Balance')||0).toLocaleString()}</strong><button class="mini-edit" onclick="openAccount(${getField(a,'id','Id')})">编辑</button></div>`).join(''):`<p class="empty-state">尚未添加真实账户。连接服务后可创建账户，或继续体验模拟数据。</p>`;return card('我的账户',`<div class="accounts-strip">${rows}</div><button class="link-btn" onclick="openAccount()">＋ 添加账户</button>`)}
function assets(){let rows=state.transactions.map(t=>`<tr><td>${t[0]}</td><td><span class="tx-icon">${categories.find(c=>c.id===t[5])?.icon||'🧾'}</span><b>${t[1]}</b></td><td><span class="tag ${t[3]<0?'expense':''}">${t[2]}</span></td><td style="color:${t[3]<0?'#d76463':'#159786'};font-weight:bold">${yuan(t[3])}</td><td>${t[4]?`<button class="icon-btn" onclick="openTransaction(${t[4]})" title="编辑">✎</button><button class="icon-btn danger" onclick="deleteTransaction(${t[4]})" title="删除">×</button>`:'—'}</td></tr>`).join('');let cash=apiState.accounts.length?apiState.accounts.reduce((s,a)=>s+Number(getField(a,'balance','Balance')||0),0):2400;return header('资产与记账','用清晰的记录，照顾每一份努力和期待。',`<div class="heading-actions"><span class="connection ${apiState.token?'online':''}">${apiState.token?'已连接账户':'模拟数据模式'}</span><button class="primary-btn" onclick="openTransaction()">＋ 记一笔</button></div>`)+`<div class="ledger-hero"><div><span class="eyebrow">本月已记录 ${state.transactions.length} 笔</span><h2>记账不只是数字，也是生活的地图</h2><p>选择一个图标分类，让 AI 更懂你的消费节奏。</p></div><div class="ledger-actions"><button onclick="quickTransaction('expense','餐饮')">🍜 餐饮</button><button onclick="quickTransaction('income','生活费')">💰 生活费</button><button onclick="quickTransaction('transfer','账目转移')">🔄 转账</button></div></div><div class="grid grid-3" style="margin-top:18px"><div class="card stat-card"><span class="label">可用现金</span><div class="value">¥${cash.toLocaleString()}</div><span class="delta">${apiState.accounts.length||2} 个账户</span></div><div class="card stat-card"><span class="label">目标储蓄</span><div class="value">¥860</div><span class="delta">正在为梦想蓄力</span></div><div class="card stat-card"><span class="label">本月结余</span><div class="value">¥${Math.max(0,state.panel.monthlyIncome-state.panel.monthlyExpenses).toLocaleString()}</div><span class="delta">结余率 42%</span></div></div><div class="grid grid-2" style="margin-top:18px">${accountsPanel()}${card('目标储蓄计划',state.goals.map(g=>`<div class="budget-row"><span style="font-size:22px">${g.icon}</span><div><b>${g.name}</b><div class="progress"><i style="width:${g.saved/g.target*100}%"></i></div><small class="muted">¥${g.saved} / ¥${g.target}</small></div><b>${Math.round(g.saved/g.target*100)}%</b></div>`).join('')+'<button class="link-btn" onclick="openGoal()">＋ 新建储蓄目标</button>')}</div><div style="margin-top:18px">${card('储蓄提醒',`<b>本月建议存入 ¥200</b><p class="muted">距离毕业旅行还差 ¥1,320，按每月 ¥200 存，7 个月即可完成。</p><button class="link-btn" onclick="showToast('已为你创建储蓄提醒')">设为提醒 →</button>`)}</div><div class="grid grid-2" style="margin-top:18px">${card('收支趋势',`<div id="trendChart" class="chart"></div>`)}${card('消费分类',`<div id="pieChart" class="chart"></div>`)}</div>${card('交易明细',`<table class="table ledger-table"><thead><tr><th>时间</th><th>记录</th><th>分类</th><th>金额</th><th></th></tr></thead><tbody>${rows||'<tr><td colspan="5" class="empty-state">暂无交易记录</td></tr>'}</tbody></table>`)}`}
function categoryOptions(type,selected){return categories.filter(c=>!type||c.type===type||type==='transfer'&&c.id===59).map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${c.icon} ${c.name}</option>`).join('')}
function updateCategoryOptions(){const type=document.querySelector('#txType').value,select=document.querySelector('#txCat');select.innerHTML=categoryOptions(type);}
function openTransaction(id=null,presetType=null,presetName=null){const existing=id?state.transactions.find(t=>t[4]===id):null;const defaultCategory=existing?.[5]||categories.find(c=>c.name===presetName)?.id||3;const type=presetType||categories.find(c=>c.id===defaultCategory)?.type||'expense';const demoAccounts=[{id:-1,name:'模拟校园卡账户',balance:1200},{id:-2,name:'模拟储蓄账户',balance:1200}];const accountOptions=(apiState.accounts.length?apiState.accounts:demoAccounts).map(a=>`<option value="${getField(a,'id','Id')||0}">${getField(a,'name','Name')||a.name} · ¥${Number(getField(a,'balance','Balance')??a.balance).toLocaleString()}</option>`).join('');openModal(`<div class="record-title"><span>✦</span><div><h2>${id?'编辑交易':'记一笔'}</h2><p class="muted">金额与分类会按你的选择自动校验</p></div></div><form id="txForm" class="form-grid"><div class="field"><label>交易类型</label><select id="txType"><option value="expense">支出</option><option value="income">收入</option><option value="borrow">借贷</option><option value="repayment">还款 / 收回</option><option value="investment">投资</option><option value="transfer">账户转账</option><option value="adjustment">勘误调整</option></select></div><div class="field"><label>金额（元）</label><input id="txAmount" type="number" min="0.01" step="0.01" value="${Math.abs(existing?.[3]||30)}" required></div><div class="field"><label>分类</label><select id="txCat"></select></div><div class="field"><label>账户</label><select id="txAccount">${accountOptions}</select></div><div class="field transfer-only"><label>转入账户</label><select id="txTarget">${accountOptions}</select></div><div class="field"><label>描述</label><input id="txDesc" value="${existing?.[1]||'日常消费'}" maxlength="80" required></div><div class="category-preview" id="categoryPreview" style="grid-column:1/-1"></div><div class="modal-actions" style="grid-column:1/-1"><button type="button" data-close class="cancel-btn">取消</button><button class="primary-btn">${id?'保存修改':'保存记录'}</button></div></form>`);let typeSelect=document.querySelector('#txType');typeSelect.value=type;updateCategoryOptions();document.querySelector('#txCat').value=defaultCategory;const refreshForm=()=>{updateCategoryOptions();document.querySelector('.transfer-only').style.display=typeSelect.value==='transfer'?'grid':'none';const c=categories.find(x=>x.id===+document.querySelector('#txCat').value);document.querySelector('#categoryPreview').innerHTML=`<span>${c?.icon||'🧾'}</span><b>${c?.name||''}</b><small>${typeLabels[c?.type]||''} · 已按接口分类 ID 映射</small>`};typeSelect.onchange=refreshForm;document.querySelector('#txCat').onchange=refreshForm;refreshForm();document.querySelector('#txForm').onsubmit=e=>saveTransaction(e,id)}
async function saveTransaction(event,id){event.preventDefault();const f=event.target,type=f.querySelector('#txType').value,categoryId=Number(f.querySelector('#txCat').value),amount=Number(f.querySelector('#txAmount').value),accountId=Number(f.querySelector('#txAccount').value),desc=f.querySelector('#txDesc').value.trim();const negative=['expense','repayment','investment'].includes(type);const payload={amount:negative?-amount:amount,description:desc,categoryId,byAccountId:accountId};try{if(apiState.token){if(type==='transfer'){const target=Number(f.querySelector('#txTarget').value);if(target===accountId)throw new Error('转入与转出账户不能相同');await callApi('/api/transaction',{method:'POST',body:JSON.stringify({...payload,amount:-amount,categoryId:59})});await callApi('/api/transaction',{method:'POST',body:JSON.stringify({...payload,amount,byAccountId:target,categoryId:59})})}else await callApi('/api/transaction',{method:id?'PUT':'POST',body:JSON.stringify(id?{...payload,id}:payload)});await refreshFinance()}else{if(id){const row=state.transactions.find(t=>t[4]===id);Object.assign(row,['刚刚',desc,categories.find(c=>c.id===categoryId)?.name||'未分类',payload.amount,id,categoryId])}else{state.transactions.unshift(['刚刚',desc,categories.find(c=>c.id===categoryId)?.name||'未分类',payload.amount,null,categoryId]);if(payload.amount<0)state.spent+=Math.abs(payload.amount)}}closeModal();showToast(apiState.token?'交易已同步至账户':'交易已保存到本地模拟数据');render()}catch(error){showToast(error.message||'保存失败')}}
function quickTransaction(type,name){openTransaction(null,type,name)}
async function deleteTransaction(id){if(!confirm('确定删除这条交易记录吗？'))return;try{if(apiState.token){await callApi('/api/transaction',{method:'DELETE',body:JSON.stringify({id})});await refreshFinance()}else state.transactions=state.transactions.filter(t=>t[4]!==id);showToast('交易记录已删除');render()}catch(error){showToast(error.message||'删除失败')}}
function openAccount(id=null){const account=id?apiState.accounts.find(a=>Number(getField(a,'id','Id'))===id):null;openModal(`<h2>${account?'编辑账户':'添加账户'}</h2><form id="accountForm" class="form-grid"><div class="field"><label>账户名称</label><input id="accountName" value="${getField(account,'name','Name')||''}" maxlength="30" required></div><div class="field"><label>账户类型</label><select id="accountType">${['现金','微信','支付宝','工商银行','中国银行','中国农业银行','建设银行','南京银行','其他'].map((n,i)=>`<option value="${i}" ${Number(getField(account,'type','Type'))===i?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label>当前余额</label><input id="accountBalance" type="number" min="0" step="0.01" value="${getField(account,'balance','Balance')||0}" required></div><div class="modal-actions" style="grid-column:1/-1"><button type="button" data-close class="cancel-btn">取消</button><button class="primary-btn">保存账户</button></div></form>`);document.querySelector('#accountForm').onsubmit=async e=>{e.preventDefault();const body={name:document.querySelector('#accountName').value,type:Number(document.querySelector('#accountType').value),balance:Number(document.querySelector('#accountBalance').value)};try{if(apiState.token){await callApi('/api/account',{method:account?'PUT':'POST',body:JSON.stringify(account?{...body,id}:body)});await refreshFinance()}else showToast('请先连接账户服务后管理真实账户');closeModal();render()}catch(error){showToast(error.message||'账户保存失败')}}}
function settings(){const p=apiState.profile||{};return header('设置与授权','你的数据由你掌控。')+`<div class="grid grid-2 settings">${card('个人信息',`<form id="profileForm"><div class="field"><label>昵称</label><input name="nickname" value="${getField(p,'nickname','Nickname')||'秾工诚'}" required></div><div class="field"><label>身份</label><select name="occupation"><option ${getField(p,'occupation','Occupation')==='在校大学生'?'selected':''}>在校大学生</option><option>研究生</option><option>初入职场</option></select></div><div class="field"><label>学校 / 公司</label><input name="school" value="${getField(p,'school','School')||'南京农业大学'}"></div><div class="field"><label>性别</label><select name="gender"><option>未填写</option><option ${getField(p,'gender','Gender')==='女'?'selected':''}>女</option><option ${getField(p,'gender','Gender')==='男'?'selected':''}>男</option></select></div><button class="primary-btn">保存修改</button></form>`)}${card('账户连接',`<div class="connection-card"><span class="connection ${apiState.token?'online':''}">${apiState.token?'已连接本机服务':'尚未连接'}</span><b>${apiState.token?'账户、交易与资料将使用后端数据':'连接后可使用真实的本地账户与交易数据'}</b><p class="muted">服务地址：${API_BASE}</p><button class="primary-btn" onclick="${apiState.token?'syncData()':'openAuth()'}">${apiState.token?'立即同步':'登录 / 注册'}</button> ${apiState.token?'<button class="cancel-btn" onclick="disconnectAccount()">断开连接</button>':''}</div><div class="disclaimer">连接仅向你本机的 ASP.NET Core 服务发送登录和财务数据。${disclaimer}</div>`)}</div><div class="card" style="margin-top:18px"><h2 class="section-title">服务说明</h2><p class="muted">${disclaimer}</p><p class="muted">所有模拟实验、财务建议和风险提示仅用于金融素养教育与辅助规划展示。</p></div>`}
async function syncData(){try{await refreshFinance();showToast('账户、交易和资料已同步');render()}catch(error){showToast('同步失败，请确认后端服务与证书状态')}}function disconnectAccount(){apiState.token='';localStorage.removeItem('qingcai_token');showToast('已切换回模拟数据模式');render()}
function render(){state.page=location.hash.slice(1)||state.page;renderNav();document.querySelector('#crumb').textContent=nav.find(x=>x[0]===state.page)?.[2]||'青财智管';document.querySelector('#view').innerHTML=pages[state.page]();document.querySelectorAll('[data-page]').forEach(el=>el.addEventListener('click',()=>{location.hash=el.dataset.page;setSidebar(false)}));if(state.page==='assets')setTimeout(drawCharts,0);if(state.page==='ai')bindChat();if(state.page==='settings')document.querySelector('#profileForm').addEventListener('submit',async e=>{e.preventDefault();try{if(apiState.token){const form=new FormData(e.target);await callApi('/api/userInfo',{method:'PUT',body:JSON.stringify(Object.fromEntries(form))});await refreshFinance()}showToast(apiState.token?'个人信息已同步':'个人信息已保存（本地模拟）')}catch(error){showToast(error.message||'保存失败')}})}
pages.assets=assets;pages.settings=settings;render();
if(API_ENABLED&&apiState.token)refreshFinance().then(()=>{apiState.connected=true;render()}).catch(()=>showToast('未能连接本机服务，当前展示模拟数据'));
else refreshPanel().then(()=>{if(state.page==='dashboard')render()});

// Category hierarchy from the supplied API catalog: RootType -> parent category -> child category.
const categoryParents={4:3,5:3,6:3,7:3,8:3,9:3,11:10,12:10,13:10,14:10,16:15,17:15,18:15,19:15,21:20,22:20,23:20,24:20,25:20,26:20,27:20,30:29,31:29,32:29,33:29,34:29,37:36,38:36,39:36,40:36,42:41,43:41,44:41,45:41,48:47,49:47,50:47,51:47,53:52,54:52,55:52,56:52,57:52};
categories.forEach(c=>c.parentId=categoryParents[c.id]??null);
const ledgerType=type=>['borrow','repayment'].includes(type)?'debt':type;
const ledgerTypes=[['expense','支出'],['income','收入'],['debt','借贷'],['investment','投资'],['transfer','账户转账'],['adjustment','勘误调整']];
const rootsForType=type=>categories.filter(c=>c.parentId===null&&ledgerType(c.type)===type);
const childrenForRoot=id=>categories.filter(c=>c.parentId===Number(id));
const optionList=list=>list.map(c=>`<option value="${c.id}">${c.icon} ${c.name}</option>`).join('');
function selectedLedgerCategory(){const root=Number(document.querySelector('#txRoot').value),child=document.querySelector('#txChild');return Number(child?.value||root)}
function updateCategoryPreview(){const c=categories.find(x=>x.id===selectedLedgerCategory()),preview=document.querySelector('#categoryPreview');if(preview)preview.innerHTML=`<span>${c?.icon||'🧾'}</span><b>${c?.name||'请选择分类'}</b><small>分类 ID：${c?.id??'-'} · ${c?.parentId?`父分类 ID：${c.parentId}`:'根分类'}</small>`}
function syncLedgerCategories(rootId){const type=document.querySelector('#txType').value,roots=rootsForType(type),root=document.querySelector('#txRoot');root.innerHTML=optionList(roots);root.value=String(rootId&&roots.some(c=>c.id===Number(rootId))?rootId:roots[0]?.id||'');const children=childrenForRoot(root.value),wrap=document.querySelector('#childCategoryField'),child=document.querySelector('#txChild');child.innerHTML=optionList(children);wrap.style.display=children.length?'grid':'none';updateCategoryPreview()}
function accountOptionsForLedger(){const accounts=apiState.accounts.length?apiState.accounts:[{id:-1,name:'模拟校园卡账户',balance:1200},{id:-2,name:'模拟储蓄账户',balance:1200}];return accounts.map(a=>{const id=getField(a,'id','Id');return `<option value="${String(id)}">${getField(a,'name','Name')||a.name} · ¥${Number(getField(a,'balance','Balance')??a.balance).toLocaleString()}</option>`}).join('')}
function ledger(){const rows=state.transactions.map(t=>`<tr><td>${t[0]}</td><td><span class="tx-icon">${categories.find(c=>c.id===t[5])?.icon||'🧾'}</span><b>${t[1]}</b></td><td><span class="tag ${t[3]<0?'expense':''}">${t[2]}</span></td><td style="color:${t[3]<0?'#d76463':'#159786'};font-weight:800">${yuan(t[3])}</td><td>${t[4]?`<button class="icon-btn" onclick="openTransaction(${t[4]})">✎</button>`:'—'}</td></tr>`).join('');return header('智能记账','三级分类记录每一笔生活，让账目更清楚。',`<button class="primary-btn" onclick="openTransaction()">＋ 新增记录</button>`)+`<div class="ledger-page-top"><section class="card ledger-guide"><span class="guide-icon">✦</span><div><b>三级分类，自动映射接口 ID</b><p>先选交易类型，再选一级与二级分类；借款和还款统一放在“借贷”里。</p></div></section><section class="card ledger-balance"><span>当前记账账户</span><b>${apiState.accounts.length?'已同步 '+apiState.accounts.length+' 个账户':'模拟模式 · 2 个账户'}</b><button class="link-btn" onclick="${apiState.token?'syncData()':'openAuth()'}">${apiState.token?'刷新账户':'连接账户'} →</button></section></div><div class="grid grid-2" style="margin-top:18px">${card('本月记账概览',`<div class="ledger-summary"><div><span>支出</span><b>¥${state.spent.toLocaleString()}</b></div><div><span>收入</span><b>¥1,500</b></div><div><span>记录笔数</span><b>${state.transactions.length}</b></div></div>`)}${card('快捷记录',`<div class="ledger-actions large"><button onclick="quickTransaction('expense','咖啡奶茶')">☕ 咖啡奶茶</button><button onclick="quickTransaction('expense','公交地铁')">🚇 公交地铁</button><button onclick="quickTransaction('income','生活费')">💰 生活费</button><button onclick="quickTransaction('debt','借款')">🤲 借贷</button></div>`)}</div>${card('全部交易',`<table class="table ledger-table"><thead><tr><th>时间</th><th>记录</th><th>分类</th><th>金额</th><th></th></tr></thead><tbody>${rows||'<tr><td colspan="5" class="empty-state">还没有记录，开始记下第一笔吧。</td></tr>'}</tbody></table>`)}`}
function openTransaction(id=null,presetType=null,presetName=null){const existing=id?state.transactions.find(t=>t[4]===id):null,existingCategory=categories.find(c=>c.id===existing?.[5]),defaultCategory=existingCategory||categories.find(c=>c.name===presetName)||categories.find(c=>c.id===3),type=presetType||ledgerType(defaultCategory.type),parentId=defaultCategory.parentId||defaultCategory.id;openModal(`<div class="record-title"><span>✦</span><div><h2>${id?'编辑交易':'记录一笔'}</h2><p class="muted">类型、一级分类、二级分类逐层选择</p></div></div><form id="txForm" class="form-grid"><div class="field"><label>交易类型</label><select id="txType">${ledgerTypes.map(([value,label])=>`<option value="${value}">${label}</option>`).join('')}</select></div><div class="field"><label>金额（元）</label><input id="txAmount" type="number" min="0.01" step="0.01" value="${Math.abs(existing?.[3]||30)}" required></div><div class="field"><label>一级分类</label><select id="txRoot"></select></div><div class="field" id="childCategoryField"><label>二级分类</label><select id="txChild"></select></div><div class="field"><label>支出 / 收入账户</label><select id="txAccount">${accountOptionsForLedger()}</select></div><div class="field transfer-only"><label>转入账户</label><select id="txTarget">${accountOptionsForLedger()}</select></div><div class="field"><label>描述</label><input id="txDesc" value="${existing?.[1]||'日常记录'}" maxlength="80" required></div><div class="category-preview" id="categoryPreview" style="grid-column:1/-1"></div><div class="modal-actions" style="grid-column:1/-1"><button type="button" data-close class="cancel-btn">取消</button><button class="primary-btn">${id?'保存修改':'保存记录'}</button></div></form>`);const txType=document.querySelector('#txType'),txRoot=document.querySelector('#txRoot'),txChild=document.querySelector('#txChild');txType.value=type;const refresh=root=>{syncLedgerCategories(root);document.querySelector('.transfer-only').style.display=txType.value==='transfer'?'grid':'none'};refresh(parentId);if(defaultCategory.parentId)txChild.value=String(defaultCategory.id);txType.onchange=()=>refresh();txRoot.onchange=()=>syncLedgerCategories(txRoot.value);txChild.onchange=updateCategoryPreview;updateCategoryPreview();document.querySelector('#txForm').onsubmit=e=>saveTransaction(e,id)}
async function saveTransaction(event,id){event.preventDefault();const f=event.target,type=f.querySelector('#txType').value,categoryId=selectedLedgerCategory(),amount=Number(f.querySelector('#txAmount').value),accountId=Number(f.querySelector('#txAccount').value),desc=f.querySelector('#txDesc').value.trim(),category=categories.find(c=>c.id===categoryId),negative=['expense','investment'].includes(type)||(type==='debt'&&category?.type==='repayment'),payload={Amount:negative?-amount:amount,Description:desc,CategoryId:categoryId,ByAccountId:accountId};try{if(apiState.token){if(!apiState.accounts.some(a=>Number(getField(a,'id','Id'))===accountId))throw new Error('请选择已同步的真实账户后再提交');if(type==='transfer'){const targetId=Number(f.querySelector('#txTarget').value);if(targetId===accountId)throw new Error('转入与转出账户不能相同');await callApi('/api/transaction',{method:'POST',body:JSON.stringify({...payload,Amount:-amount,CategoryId:59,ByAccountId:accountId})});await callApi('/api/transaction',{method:'POST',body:JSON.stringify({...payload,Amount:amount,CategoryId:59,ByAccountId:targetId})})}else await callApi('/api/transaction',{method:id?'PUT':'POST',body:JSON.stringify(id?{...payload,Id:id}:payload)});await refreshFinance()}else{const localAmount=payload.Amount;if(id){const row=state.transactions.find(t=>t[4]===id);Object.assign(row,['刚刚',desc,category?.name||'未分类',localAmount,id,categoryId])}else state.transactions.unshift(['刚刚',desc,category?.name||'未分类',localAmount,null,categoryId]);if(localAmount<0)state.spent+=Math.abs(localAmount)}closeModal();showToast(apiState.token?'交易已按所选账户同步':'交易已保存到本地模拟数据');render()}catch(error){showToast(error.message||'保存失败')}}
function quickTransaction(type,name){openTransaction(null,type,name)}
pages.ledger=ledger;render();

